export type LabelMergeResult =
  | { readonly ok: true; readonly label: IssueLabel; readonly issuesRelabelled: number }
  | { readonly ok: false; readonly missingLabelId: LabelId };

/**
 * Folds `sourceLabelId` into `targetLabelId` in one transaction. Every issue
 * that carried the source carries the target afterwards, exactly once, and the
 * source row is deleted. Both rows are read inside the transaction, so when
 * either is missing from `orgId` nothing is written.
 */
export async function mergeLabelInto(
  orgId: OrgId,
  sourceLabelId: LabelId,
  targetLabelId: LabelId,
): Promise<LabelMergeResult> {
  return getDb().transaction((tx): LabelMergeResult => {
    const source = tx
      .select()
      .from(labels)
      .where(and(orgPredicate(labels.orgId, orgId), eq(labels.id, sourceLabelId)))
      .get();
    if (!source) return { ok: false, missingLabelId: sourceLabelId };

    const target = tx
      .select()
      .from(labels)
      .where(and(orgPredicate(labels.orgId, orgId), eq(labels.id, targetLabelId)))
      .get();
    if (!target) return { ok: false, missingLabelId: targetLabelId };

    const issuesRelabelled =
      tx
        .select({ value: count() })
        .from(issueLabels)
        .where(
          and(
            orgPredicate(issueLabels.orgId, orgId),
            eq(issueLabels.labelId, sourceLabelId),
          ),
        )
        .get()?.value ?? 0;

    // Issues that already carry the target are skipped by the move: their
    // source rows stay behind and are removed by the delete that follows.
    const taken = alias(issueLabels, "taken_issue_labels");
    tx.update(issueLabels)
      .set({ labelId: targetLabelId })
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.labelId, sourceLabelId),
          notInArray(
            issueLabels.issueId,
            tx
              .select({ issueId: taken.issueId })
              .from(taken)
              .where(
                and(orgPredicate(taken.orgId, orgId), eq(taken.labelId, targetLabelId)),
              ),
          ),
        ),
      )
      .run();

    tx.delete(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.labelId, sourceLabelId),
        ),
      )
      .run();

    tx.delete(labels)
      .where(and(orgPredicate(labels.orgId, orgId), eq(labels.id, sourceLabelId)))
      .run();

    return { ok: true, label: toLabel(target), issuesRelabelled };
  });
}

