/**
 * Folds the source label into the target: every issue that carried the source
 * carries the target instead, and the source label is deleted. The effect is a
 * delete at scale, so it takes the same permission as `deleteLabel`.
 */
export async function mergeLabels(
  actor: Actor,
  input: MergeLabelsInput,
): Promise<{ label: IssueLabel; issuesRelabelled: number }> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "project:archive", orgResource(input.orgId));

  // Re-checked here because callers can bypass `mergeLabelsSchema`.
  if (input.sourceLabelId === input.targetLabelId) {
    throw new Error("A label cannot be merged into itself");
  }

  const merged = await labelRepo.mergeLabelInto(
    input.orgId,
    input.sourceLabelId,
    input.targetLabelId,
  );
  if (!merged.ok) throw new NotFoundError("Label", merged.missingLabelId);

  return { label: merged.label, issuesRelabelled: merged.issuesRelabelled };
}

