/**
 * Label merge: relabelling, the no-duplicate move, and the guard rails.
 */
import { afterAll, beforeAll, describe, expect, it } from "vitest";

import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { mergeLabelsSchema } from "@/schemas/label";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import { NotFoundError } from "@/server/services/_support";
import * as labelService from "@/server/services/label-service";
import type { IssueLabel } from "@/types/issue";
import type { Actor } from "@/types/member";
import {
  createTenant,
  issueInput,
  type Tenant,
  useTemporaryDatabase,
} from "../server/_support/fixtures";

let cleanup: () => void;
let nextIssueNumber = 1;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

async function makeLabel(tenant: Tenant, name: string): Promise<IssueLabel> {
  return labelRepo.insertLabel({
    orgId: tenant.org.id,
    name,
    color: "#94a3b8",
    description: null,
  });
}

async function makeIssue(
  tenant: Tenant,
  labelIds: readonly IssueLabel["id"][],
  archived = false,
) {
  const issue = await issueRepo.insertIssue(
    { ...issueInput(tenant.org.id, tenant.project.id), labelIds },
    tenant.userIds.owner,
    nextIssueNumber++,
  );
  if (archived) await issueRepo.archiveIssue(tenant.org.id, issue.id);
  return issue;
}

async function labelIdsOf(tenant: Tenant, issueId: string): Promise<string[]> {
  const byIssue = await labelRepo.listLabelsForIssues(tenant.org.id, [
    issueId as never,
  ]);
  return (byIssue[issueId] ?? []).map((label) => label.id).sort();
}

function mergeInput(
  tenant: Tenant,
  sourceLabelId: string,
  targetLabelId: string,
) {
  return {
    orgId: tenant.org.id,
    sourceLabelId: sourceLabelId as IssueLabel["id"],
    targetLabelId: targetLabelId as IssueLabel["id"],
  };
}

describe("services/label-service mergeLabels", () => {
  it("moves source issues onto the target once and deletes the source", async () => {
    const tenant = await createTenant("label-merge-happy", "growth");
    const admin: Actor = tenant.actors.admin;
    const source = await makeLabel(tenant, "defect");
    const target = await makeLabel(tenant, "bug");
    const other = await makeLabel(tenant, "ui");

    const sourceOnly = await makeIssue(tenant, [source.id]);
    const sourceAndTarget = await makeIssue(tenant, [source.id, target.id]);
    const archivedSource = await makeIssue(tenant, [source.id, other.id], true);
    const untouched = await makeIssue(tenant, [other.id]);

    const result = await labelService.mergeLabels(
      admin,
      mergeInput(tenant, source.id, target.id),
    );

    expect(result).toEqual({ label: target, issuesRelabelled: 3 });
    expect(await labelIdsOf(tenant, sourceOnly.id)).toEqual([target.id]);
    expect(await labelIdsOf(tenant, sourceAndTarget.id)).toEqual([target.id]);
    expect(await labelIdsOf(tenant, archivedSource.id)).toEqual(
      [other.id, target.id].sort(),
    );
    expect(await labelIdsOf(tenant, untouched.id)).toEqual([other.id]);

    const remaining = await labelRepo.listLabels(tenant.org.id);
    expect(remaining.map((label) => label.name)).toEqual(["bug", "ui"]);
  });

  it("rejects a merge into the same label and changes nothing", async () => {
    const tenant = await createTenant("label-merge-self", "growth");
    const label = await makeLabel(tenant, "defect");
    const issue = await makeIssue(tenant, [label.id]);

    await expect(
      labelService.mergeLabels(
        tenant.actors.admin,
        mergeInput(tenant, label.id, label.id),
      ),
    ).rejects.toThrow(/merged into itself/);

    expect(await labelIdsOf(tenant, issue.id)).toEqual([label.id]);
    expect(await labelRepo.listLabels(tenant.org.id)).toHaveLength(1);
  });

  it("rejects a label that is missing from the org, even one from another org, and changes nothing", async () => {
    const tenant = await createTenant("label-merge-missing-a", "growth");
    const foreign = await createTenant("label-merge-missing-b", "growth");
    const source = await makeLabel(tenant, "defect");
    const target = await makeLabel(tenant, "bug");
    const foreignLabel = await makeLabel(foreign, "bug");
    const issue = await makeIssue(tenant, [source.id]);

    await expect(
      labelService.mergeLabels(
        tenant.actors.admin,
        mergeInput(tenant, source.id, foreignLabel.id),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      labelService.mergeLabels(
        tenant.actors.admin,
        mergeInput(tenant, foreignLabel.id, target.id),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);

    expect(await labelIdsOf(tenant, issue.id)).toEqual([source.id]);
    expect((await labelRepo.listLabels(tenant.org.id)).map((l) => l.id).sort()).toEqual(
      [source.id, target.id].sort(),
    );
    expect(await labelRepo.listLabels(foreign.org.id)).toHaveLength(1);
  });

  it("rejects an input for another org and an actor without archive permission", async () => {
    const tenant = await createTenant("label-merge-guards", "growth");
    const other = await createTenant("label-merge-guards-other", "growth");
    const source = await makeLabel(tenant, "defect");
    const target = await makeLabel(tenant, "bug");
    const issue = await makeIssue(tenant, [source.id]);

    await expect(
      labelService.mergeLabels(tenant.actors.admin, {
        ...mergeInput(tenant, source.id, target.id),
        orgId: other.org.id,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      labelService.mergeLabels(
        tenant.actors.member,
        mergeInput(tenant, source.id, target.id),
      ),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    expect(await labelIdsOf(tenant, issue.id)).toEqual([source.id]);
    expect(await labelRepo.listLabels(tenant.org.id)).toHaveLength(2);
  });
});

describe("schemas/label mergeLabelsSchema", () => {
  it("accepts two different labels and rejects the same label twice", async () => {
    const tenant = await createTenant("label-merge-schema", "growth");
    const a = await makeLabel(tenant, "defect");
    const b = await makeLabel(tenant, "bug");

    expect(
      mergeLabelsSchema.safeParse(mergeInput(tenant, a.id, b.id)).success,
    ).toBe(true);
    expect(
      mergeLabelsSchema.safeParse(mergeInput(tenant, a.id, a.id)).success,
    ).toBe(false);
  });
});

